import{z as B,x as p,o as i,c as A,q as n,j as t,D as E,d as o,s,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"古诺数量竞争","description":"","frontmatter":{"title":"古诺数量竞争","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/cournot-oligopoly.md","filePath":"econ/cournot-oligopoly.md","lastUpdated":1791413859000}'),_={name:"econ/cournot-oligopoly.md"};function d(m,a,h,D,c,C){const r=p("Mermaid");return i(),A("div",null,[a[2]||(a[2]=n('<h1 id="古诺数量竞争" tabindex="-1">古诺数量竞争 <a class="header-anchor" href="#古诺数量竞争" aria-label="Permalink to &quot;古诺数量竞争&quot;">​</a></h1><div class="epigraph"><p>两家矿主各自选定产量，价格由总产量在需求上读出；均衡是每家都在对方产量给定时做到最优。</p><footer>—— 据 Cournot, Recherches sur les principes mathématiques de la théorie des richesses, 1838 整理</footer></div><p><a href="/econ/peak-load-pricing">上一课</a>（高峰负荷定价）。仍是一家卖方，最多把需求拆成组别。本课不重讲按弹性加价。缺口是：\\(n=1\\) 拿掉之后，若剩下几家同质产品的厂商，谁也不是面对整条 \\(P(Q)\\) 的垄断者，谁也不是上一课序完全竞争里的价格接受者。必须给一个同时选择的策略变量：Cournot 选的是数量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两家，成本 \\(c_i(q_i)\\)，反需求 \\(P(q_1+q_2)\\)。厂商 \\(i\\) 把对方产量当给定，解</p> \\[\\max_{q_i}\\, P(q_i+q_j)q_i-c_i(q_i). \\]<p>一阶条件是 \\(\\mathrm{MR}_i=\\mathrm{MC}_i\\)，其中 \\(\\mathrm{MR}_i=P+q_i P&#39;\\)，与垄断同一公式，只是弹性要按<strong>剩余需求</strong>来算。相互最优反应的交点是古诺均衡。缺口不是从零讲「什么是博弈」——纳什课序在后——而是把垄断的 MR 改成「给定别人已经放在市场上的数量」。勒纳变成 \\(L_i=s_i/|\\varepsilon|\\)，\\(s_i\\) 是份额：一家时 \\(s_i=1\\)，回到垄断课；份额趋于零时 \\(L_i\\to 0\\)，回到完全竞争。</p><p>对称、常数 MC、线性需求时，均衡总产量在垄断与竞争之间，随 \\(n\\) 增加趋向 \\(P=\\mathrm{MC}\\)。这给出市场结构课序的连续对照，不必另起一套福利语言。</p><p><span class="marginnote">数字实例：线性需求 \\(P=100-Q\\)、\\(\\mathrm{MC}=20\\) 时，对称双寡头各产约 26.7、市价约 46.7；垄断则只产 40、卖 60、单家加价 40。双寡头的总产量更靠近竞争端，价格明显更低。</span></p><h3 id="反应函数不是供给曲线" tabindex="-1">反应函数不是供给曲线 <a class="header-anchor" href="#反应函数不是供给曲线" aria-label="Permalink to &quot;反应函数不是供给曲线&quot;">​</a></h3><p>\\(q_1^*(q_2)\\) 是：对方若真产 \\(q_2\\)，我的最优产量。它向下倾斜（策略替代，在通常需求下）。行业供给曲线是价格接受加总，上一课序才有。把反应函数画成供给、再与需求相交，会把策略互动读成竞争均衡，份额公式全部失效。</p><p><span class="marginnote">均衡要求双方同时猜对对方的产量。这比价格接受强，比后课扩展式的先动承诺弱：没有谁先写进合同。存在性、混合策略留给博弈课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 \\((q_1,q_2)\\) 平面上画两条反应曲线，交点即均衡。稳定的比较静态：成本下降，自己产量升、对方产量降，总产量升、价格降。合谋相当于回到垄断总产量再按某种规则分；古诺是非合作点，利润低于合谋、高于竞争。本课不引入折扣因子与惩罚，重复博弈在后课程。</p><p>产品同质、一次同时选数量，是本课菜单。若策略变量是价格，下一课伯川德会显示：同一成本结构可以给出完全不同的 \\(P\\)。不要在本课预先把价格竞争写成「更激烈」的口头禅，先把数量这一端钉死。</p><p><span class="marginnote">术语翻译：「策略替代」指你产得越多、我少产更划算，反应曲线向下倾斜；换成差异产品的价格竞争时可能是「策略互补」——你降价我也得跟着降，反应曲线向上。方向不同，均衡与比较静态都跟着变。</span></p>',16)),(i(),t(l,null,{default:E(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E5%9E%84%E6%96%AD%EF%BC%9A%E9%9D%A2%E5%AF%B9%E6%95%B4%E6%9D%A1%20P(Q)%22%5D%20--%3E%20RIV%5B%22%E5%AF%B9%E6%96%B9%E4%BA%A7%E9%87%8F%E7%BB%99%E5%AE%9A%22%5D%0A%20%20RIV%20--%3E%20BR%5B%22%E5%8F%8D%E5%BA%94%E5%87%BD%E6%95%B0%20q_i*(q_j)%22%5D%0A%20%20BR%20--%3E%20EQ%5B%22%E4%BA%A4%E7%82%B9%EF%BC%9A%E5%8F%A4%E8%AF%BA%E5%9D%87%E8%A1%A1%22%5D%0A%20%20EQ%20--%3E%20LER%5B%22L_i%20%3D%20s_i%20%2F%20%7C%CE%B5%7C%22%5D%0A%20%20EQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%8B%A5%E6%94%B9%E9%80%89%E4%BB%B7%E6%A0%BC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"线性需求、对称常 MC 可解出闭式：双寡头产量介于垄断与竞争之间，\\(n\\) 增大则加价按份额缩小。不对称成本时低 MC 者份额更大，行业勒纳是份额加权。本课只写到份额进入公式。",-1)),a[4]||(a[4]=e("p",null,"产能在本课是足够的：想产多少就能产多少，MC 已含全部成本。产能先定、再在市场上拼价格，是伯川德课的 Kreps–Scheinkman 接口。",-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"剩余需求的机制：别人已经供给 \\(q_j\\)，自己面对的是 \\(P(\\,\\cdot\\,+q_j)\\)，斜率仍是 \\(P'\\)，但截距更低。份额进入勒纳，是因为压价损失只打在自己的 \\(q_i\\) 上，不是打在全部 \\(Q\\) 上。\\(n\\) 变大时每家 \\(s_i\\) 变小，加价被稀释——这是结构，不是偏好变化。",-1)),(i(),t(l,null,{default:E(()=>[s(r,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20QJ%5B%22%E5%AF%B9%E6%89%8B%E5%B7%B2%E4%BE%9B%E5%BA%94%20q_j%22%5D%20--%3E%20RD%5B%22%E5%89%A9%E4%BD%99%E9%9C%80%E6%B1%82%EF%BC%9AP(%C2%B7%2Bq_j)%EF%BC%8C%E6%88%AA%E8%B7%9D%E6%9B%B4%E4%BD%8E%22%5D%0A%20%20RD%20--%3E%20LOSS%5B%22%E9%99%8D%E4%BB%B7%E7%9A%84%E6%8D%9F%E5%A4%B1%E5%8F%AA%E8%90%BD%E5%9C%A8%E8%87%AA%E5%B7%B1%E7%9A%84%20q_i%20%E4%B8%8A%22%5D%0A%20%20LOSS%20--%3E%20L%5B%22%E5%8D%95%E5%AE%B6%E5%8A%A0%E4%BB%B7%20L_i%20%3D%20s_i%20%2F%20%7C%CE%B5%7C%22%5D%0A%20%20NUP%5B%22%E8%BF%9B%E5%85%A5%E8%80%85%E4%BD%BF%20n%20%E5%A2%9E%E5%A4%A7%22%5D%20--%3E%20S%5B%22%E6%AF%8F%E5%AE%B6%E4%BB%BD%E9%A2%9D%20s_i%20%E5%8F%98%E5%B0%8F%22%5D%0A%20%20S%20--%3E%20DIL%5B%22%E5%8A%A0%E4%BB%B7%E8%A2%AB%E7%A8%80%E9%87%8A%EF%BC%9A%E4%BB%B7%E6%A0%BC%E6%BB%91%E5%90%91%20MC%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">直觉类比：对方先倒走一桶矿泉水，泉边顾客已被他接走一批，你面对的需求表整体下移；你再降 1 元抢客时，压价的损失只算在你自己的销量头上——这就是「份额进入勒纳公式」的来源。</span></p><p>与完全竞争的衔接：价格接受等于把 \\(P&#39;\\) 当成零（自己看不见对市价的影响）。古诺把这一项留在 MR 里。进入若把 \\(n\\) 撑大，价格向 \\(\\mathrm{MC}\\) 靠拢，与长期竞争的零利润不是同一句话：古诺即使自由进入，只要产品同质且同时选数量，仍可能留下加价，取决于进入后的 \\(n\\) 与固定成本。本课不把进入做成内生，以免与完全竞争课的零利润焊死。</p><p><span class="marginnote">Cournot 原文用的是矿泉。引用 1838 年的《财富理论的数学原理研究》即可。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>产量与价格哪一个是真策略，要看制度：产能难调、市场上拼的是量，古诺像；价目表先贴出去，伯川德像。差异产品会把策略替代减弱甚至变成策略互补，霍特林课再处理。也不在这里写拍卖或限价簿撮合——同时选 \\(q\\) 是抽象市场，没有订单。</p><p>反应曲线若因边际成本下降而向上，均衡可能丢失。合谋把全部降价效应内部化，产量回到垄断，但需要可执行契约——无名氏定理是博弈课。进入可叠在古诺上：正利润招来第 \\(n+1\\) 家，直到盖住进入成本，加价不必降到零。</p><p>后课默认：同质寡占的数量均衡由相互反应给出，单家勒纳带份额。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>古诺把垄断的 MR 改成剩余需求上的 MR；均衡是反应函数的交点。</li><li>\\(L_i=s_i/|\\varepsilon|\\)：一家回到勒纳，份额趋于零回到竞争。</li><li>反应函数不是行业供给；合谋与重复惩罚不在本课。</li><li>下一课把策略变量换成价格，并问产能为何不让价格落到 MC。</li><li>出处：Cournot, <em>Recherches</em>, 1838；Mas-Colell, Whinston and Green 第 12 章。</li></ul>',9))])}const P=B(_,[["render",d]]);export{u as __pageData,P as default};
